/* Fetch polyfill for old Android WebView / IE11 — loads only if native fetch missing */
if (typeof fetch === "undefined") {
  window.fetch = function (url, opts) {
    return new Promise(function (resolve, reject) {
      var xhr = new XMLHttpRequest();
      xhr.open(opts && opts.method || "GET", url);
      xhr.withCredentials = true;
      if (opts && opts.headers) {
        Object.keys(opts.headers).forEach(function (k) {
          xhr.setRequestHeader(k, opts.headers[k]);
        });
      }
      xhr.onload = function () {
        var headers = {};
        xhr.getAllResponseHeaders().trim().split("\n").forEach(function (line) {
          var parts = line.split(":");
          headers[parts[0].trim()] = parts.slice(1).join(":").trim();
        });
        resolve({
          ok: xhr.status >= 200 && xhr.status < 300,
          status: xhr.status,
          statusText: xhr.statusText,
          headers: { get: function (k) { return headers[k.toLowerCase()]; } },
          json: function () { return Promise.resolve(JSON.parse(xhr.responseText)); },
          text: function () { return Promise.resolve(xhr.responseText); },
        });
      };
      xhr.onerror = function () { reject(new TypeError("Network request failed")); };
      xhr.send(opts && opts.body || null);
    });
  };
}
